from sympy import *
def saw(x): x=Rational(x); return 0 if x==floor(x) else x-floor(x)-Rational(1,2)
def s(h,k): return sum(saw(Rational(r,k))*saw(Rational(h*r,k)) for r in range(1,k))
def sym(m,n): return 12*abs(n)*s(m,abs(n)) if n!=0 else 2*m
m,n=5,7; assert m*sym(m,n)-n*sym(-n,m)==1+m**2+n**2-3*m*n
